class Solution {
public:
    int numOfSubarrays(vector<int>& arr) {
        const int MOD = 1000000007;
        long long result = 0;
        int evenCount = 1, oddCount = 0;
        int prefix = 0;
        for (int x : arr) {
            prefix += x;
            if (prefix & 1) {
                result += evenCount;
                oddCount++;
            } else {
                result += oddCount;
                evenCount++;
            }
            result %= MOD;
        }
        return (int)result;
    }
};
